using System;
using System.Collections.Generic;
using UnityEngine;

namespace Megastructure
{
    /// <summary>Fog domain selected per material by the integer property _AbDomain (14.2).</summary>
    public enum FogDomain { Shaft = 0, Tunnel = 1, Exterior = 2 }

    /// <summary>
    /// Base material identifiers. Every id has exactly one base material asset generated by the editor build script
    /// (Assets/_Game/Materials/M_*.mat), referenced by the MaterialLibrary asset that the scene references, so the shaders
    /// are always included in player builds.
    /// </summary>
    public enum MatId
    {
        ConcreteBoard = 0,   // M_ConcreteBoard: board-formed walls (triplanar, analytic joints, tie holes, streaks)
        ConcreteFloor,       // worn concrete floor (roughness 0.45, worn centre path)
        ConcreteCyl,         // M_ConcreteCyl: cylinders, UV0 = (arc length m, height m)
        SteelPainted,        // M_SteelPainted: STEEL_DARK, edge wear from vertex G, rust by noise
        SteelWeathered,      // heavier wear/rust variant (fan, crank pits)
        RodPolished,         // M_RodPolished: metallic 1, roughness 0.30, shader env term
        Grating,             // M_Grating: alpha-to-coverage analytic grating
        Facade,              // M_Facade shader tier: window grid with fake depth (14.7.3)
        FacadeModule,        // near-tier module mesh windows (real reveals) - same window hash as Facade
        LampAmber,           // M_Lamp: AMBER emissive 8.0
        LampCold,            // cold fixture strips / lamp heads (COLD_LAMP emissive)
        Glow,                // camera-facing glow sprites with a minimum pixel size (lamp dots, freight lights, bolt)
        BeamWedge,           // M_BeamWedge: additive analytic beam prism (14.7.4)
        Lattice,             // M_Lattice: honeycomb tier-2 shader field (14.7.7)
        Cable,               // M_Cable: rubber with ThinLine
        DoorLeaf,            // M_DoorLeaf
        ProxyCard,           // unlit fogged flat colour card (equal-luma proxies, dark interior cards)
        GradientCard,        // unlit emissive vertical-gradient card (bore card, dark card, doorway glow)
        HoneyTube,           // honeycomb tube walls: concrete with exp(-depth/140) darkening, domain 2
        ShadowCaster,        // invisible shadow-only material (player shadow capsule)
        Count
    }

    /// <summary>
    /// Runtime access to the generated base materials and their fog-domain / tweak variants.
    /// Variants are cloned once (at build time, never per frame) and cached by key.
    /// </summary>
    [CreateAssetMenu(menuName = "Megastructure/Material Library")]
    public sealed class MaterialLibrary : ScriptableObject
    {
        [Tooltip("Indexed by MatId")]
        public Material[] materials = new Material[(int)MatId.Count];

        public Material skybox;
        public Material finalDither;
        public Texture2D noiseTex;
        public Texture2D streakTex;

        [NonSerialized] readonly Dictionary<string, Material> _variants = new Dictionary<string, Material>();

        public static MaterialLibrary Instance { get; private set; }

        public void MakeCurrent() { Instance = this; }

        public Material this[MatId id] => Base(id);

        public Material Base(MatId id)
        {
            var m = materials[(int)id];
            if (m == null) Debug.LogError($"MaterialLibrary: missing base material {id}");
            return m;
        }

        /// <summary>The base material in another fog domain (cloned once).</summary>
        public Material Get(MatId id, FogDomain domain)
        {
            if (domain == FogDomain.Shaft) return Base(id);
            return Variant(id, "d" + (int)domain, m => m.SetFloat(ShaderIds.AbDomain, (int)domain));
        }

        /// <summary>A cached clone of a base material with a one-off tweak (colour, roughness, flags). key must be unique per tweak.</summary>
        public Material Variant(MatId id, string key, Action<Material> tweak)
        {
            string full = id + "/" + key;
            if (_variants.TryGetValue(full, out var v) && v != null) return v;
            v = new Material(Base(id)) { name = Base(id).name + "_" + key };
            tweak?.Invoke(v);
            _variants[full] = v;
            return v;
        }

        /// <summary>Every variant created so far (for the shader warm-up). No allocation: enumerates the cache.</summary>
        public Dictionary<string, Material>.ValueCollection AllVariants => _variants.Values;

        /// <summary>Variant of a variant: domain plus tweak.</summary>
        public Material Variant(MatId id, FogDomain domain, string key, Action<Material> tweak)
        {
            return Variant(id, "d" + (int)domain + "/" + key, m =>
            {
                m.SetFloat(ShaderIds.AbDomain, (int)domain);
                tweak?.Invoke(m);
            });
        }
    }
}
